function KPI({ label, value, sub, color }) {
  return (
    <div style={{ background:"rgba(255,255,255,0.04)", border:`1px solid ${color}40`, borderLeft:`3px solid ${color}`, borderRadius:8, padding:"14px 18px" }}>
      <div style={{ fontSize:11, color:"#777", textTransform:"uppercase", letterSpacing:1, marginBottom:4 }}>{label}</div>
      <div style={{ fontSize:24, fontWeight:700, color, fontFamily:"monospace" }}>{value}</div>
      {sub && <div style={{ fontSize:11, color:"#555", marginTop:2 }}>{sub}</div>}
    </div>
  );
}

function Sel({ label, value, onChange, options }) {
  return (
    <div>
      <div style={{ fontSize:11, color:"#555", marginBottom:4, textTransform:"uppercase", letterSpacing:1 }}>{label}</div>
      <select value={value} onChange={e => onChange(e.target.value)}
        style={{ background:"#0D0F14", border:"1px solid #2a2d3a", borderRadius:6, color:"#E8E8E8", padding:"7px 10px", fontSize:13 }}>
        {options.map(o => <option key={o.value} value={o.value}>{o.label}</option>)}
      </select>
    </div>
  );
}

const PARAMS = [
  { key:"horas", label:"Horas trabajadas", color:"#F4A027" },
  { key:"combustible", label:"Combustible (L)", color:"#E8622A" },
];

function EquipoDesgaste({ equipo }) {
  const [open, setOpen] = useState(false);
  const fmtDate = d => d ? d.split('-').reverse().join('/') : '';
  return (
    <div style={{ background:"#13161e", borderRadius:10, border:"1px solid #1e2130", overflow:"hidden" }}>
      <div onClick={() => setOpen(!open)}
        style={{ display:"flex", alignItems:"center", justifyContent:"space-between", padding:"14px 18px", cursor:"pointer", userSelect:"none" }}>
        <div style={{ display:"flex", alignItems:"center", gap:14 }}>
          <div style={{ color:"#F4A027", fontWeight:700, fontSize:15 }}>{equipo.interno}</div>
          <div style={{ color:"#666", fontSize:12 }}>{equipo.tipo}</div>
          <div style={{ background:"#2a1208", color:"#E76F51", borderRadius:20, padding:"2px 10px", fontSize:12, fontWeight:600 }}>
            {equipo.items.length} registro{equipo.items.length !== 1 ? "s" : ""}
          </div>
        </div>
        <div style={{ color:"#444", fontSize:18, transition:"transform 0.2s", transform:open?"rotate(180deg)":"rotate(0deg)" }}>▾</div>
      </div>
      {open && (
        <div style={{ borderTop:"1px solid #1e2130" }}>
          <table style={{ width:"100%", borderCollapse:"collapse", fontSize:13 }}>
            <thead>
              <tr style={{ background:"#0D0F14" }}>
                {["Fecha","Parte #","Operador","Elemento de desgaste"].map(h => (
                  <th key={h} style={{ padding:"8px 14px", textAlign:"left", color:"#555", fontSize:11, textTransform:"uppercase", letterSpacing:1 }}>{h}</th>
                ))}
              </tr>
            </thead>
            <tbody>
              {equipo.items.map((item, i) => (
                <tr key={i} style={{ borderTop:"1px solid #1a1d24", background:i%2===0?"transparent":"rgba(255,255,255,0.015)" }}>
                  <td style={{ padding:"9px 14px", color:"#888" }}>{fmtDate(item.fecha)}</td>
                  <td style={{ padding:"9px 14px", color:"#555" }}>#{item.nParte}</td>
                  <td style={{ padding:"9px 14px" }}>{item.operador}</td>
                  <td style={{ padding:"9px 14px", color:"#E76F51", fontWeight:500 }}>⚠ {item.desgaste}</td>
                </tr>
              ))}
            </tbody>
          </table>
        </div>
      )}
    </div>
  );
}

export default function App() {
  const allDates = useMemo(() => [...new Set(RAW_DATA.map(r => r.fecha))].sort(), []);
  const allTipos = useMemo(() => ["Todos", ...new Set(RAW_DATA.map(r => r.tipo))].sort(), []);
  const allYears = useMemo(() => [...new Set(allDates.map(d => d.slice(0,4)))].sort(), [allDates]);

  const [mode, setMode] = useState("dia");
  const [selectedDate, setSelectedDate] = useState(() => allDates[allDates.length-1]);

  const [fromYear,  setFromYear]  = useState(() => allYears[0]);
  const [fromMonth, setFromMonth] = useState("01");
  const [fromDay,   setFromDay]   = useState("01");
  const [toYear,    setToYear]    = useState(() => allYears[allYears.length-1]);
  const [toMonth,   setToMonth]   = useState("06");
  const [toDay,     setToDay]     = useState("30");

  const [filterTipo,   setFilterTipo]   = useState("Todos");
  const [filterEquipo, setFilterEquipo] = useState("Todos");
  const [tab,      setTab]      = useState("resumen");
  const [paramKey, setParamKey] = useState("horas");

  const dateFrom = `${fromYear}-${fromMonth}-${fromDay}`;
  const dateTo   = `${toYear}-${toMonth}-${toDay}`;

  const filtered = useMemo(() => RAW_DATA.filter(r => {
    const inDate   = mode === "dia" ? r.fecha === selectedDate : r.fecha >= dateFrom && r.fecha <= dateTo;
    const inTipo   = filterTipo === "Todos" || r.tipo === filterTipo;
    const inEquipo = filterEquipo === "Todos" || r.interno === filterEquipo;
    return inDate && inTipo && inEquipo;
  }), [mode, selectedDate, dateFrom, dateTo, filterTipo, filterEquipo]);

  const allEquipos = useMemo(() => {
    const base = RAW_DATA.filter(r => filterTipo === "Todos" || r.tipo === filterTipo);
    return ["Todos", ...new Set(base.map(r => r.interno))].sort();
  }, [filterTipo]);

  const totalHoras = filtered.reduce((a,r) => a+r.horas, 0);
  const totalComb  = filtered.reduce((a,r) => a+r.combustible, 0);
  const equiposAct = new Set(filtered.map(r => r.interno)).size;
  const operadores = new Set(filtered.map(r => r.operador)).size;
  const alertas    = filtered.filter(r => r.desgaste && r.desgaste !== "Sin consumo de desgaste").length;
  const diasCub    = new Set(filtered.map(r => r.fecha)).size;

  const horasPorTipo = useMemo(() => {
    const acc = {};
    filtered.forEach(r => { acc[r.tipo] = (acc[r.tipo]||0) + r.horas; });
    return Object.entries(acc).map(([tipo,horas]) => ({tipo,horas})).sort((a,b) => b.horas-a.horas);
  }, [filtered]);

  const porEquipo = useMemo(() => {
    const acc = {};
    filtered.forEach(r => {
      if (!acc[r.interno]) acc[r.interno] = {interno:r.interno,tipo:r.tipo,horas:0,combustible:0,partes:0};
      acc[r.interno].horas += r.horas;
      acc[r.interno].combustible += r.combustible;
      acc[r.interno].partes += 1;
    });
    return Object.values(acc).sort((a,b) => b.horas-a.horas);
  }, [filtered]);

  const desgastePorEquipo = useMemo(() => {
    const acc = {};
    filtered.filter(r => r.desgaste && r.desgaste !== "Sin consumo de desgaste").forEach(r => {
      if (!acc[r.interno]) acc[r.interno] = { interno:r.interno, tipo:r.tipo, items:[] };
      acc[r.interno].items.push({ fecha:r.fecha, desgaste:r.desgaste, operador:r.operador, nParte:r.nParte });
    });
    return Object.values(acc).sort((a,b) => b.items.length - a.items.length);
  }, [filtered]);

  const proyectos = useMemo(() => {
    const acc = {};
    filtered.forEach(r => { if(r.proyecto) acc[r.proyecto] = (acc[r.proyecto]||0)+r.horas; });
    return Object.entries(acc).map(([name,value]) => ({name,value})).sort((a,b) => b.value-a.value);
  }, [filtered]);

  const serieTemporal = useMemo(() => {
    const rango = mode === "dia" ? [selectedDate] : allDates.filter(d => d >= dateFrom && d <= dateTo);
    return rango.map(d => {
      const dr = filtered.filter(r => r.fecha === d);
      return { dia: d.slice(5).replace('-','/'), [paramKey]: parseFloat(dr.reduce((a,r) => a+r[paramKey],0).toFixed(1)) };
    });
  }, [filtered, mode, selectedDate, dateFrom, dateTo, allDates, paramKey]);

  const fmtDate = d => d ? d.split('-').reverse().join('/') : '';
  const paramColor = PARAMS.find(p => p.key===paramKey)?.color || "#F4A027";
  const paramLabel = PARAMS.find(p => p.key===paramKey)?.label || paramKey;

  const yearOpts  = allYears.map(y => ({value:y, label:y}));
  const monthOpts = MESES.map((m,i) => ({value:String(i+1).padStart(2,'0'), label:m}));
  const dayOpts   = Array.from({length:31},(_,i) => ({value:String(i+1).padStart(2,'0'), label:String(i+1)}));

  return (
    <div style={{ minHeight:"100vh", background:"#0D0F14", color:"#E8E8E8", fontFamily:"'DM Sans','Segoe UI',sans-serif" }}>

      <div style={{ background:"#13161e", borderBottom:"1px solid #1e2130", padding:"16px 24px", display:"flex", alignItems:"center", justifyContent:"space-between", flexWrap:"wrap", gap:10 }}>
        <div style={{ display:"flex", alignItems:"center", gap:12 }}>
          <div style={{ width:40, height:40, borderRadius:8, background:"linear-gradient(135deg,#F4A027,#E8622A)", display:"flex", alignItems:"center", justifyContent:"center", fontSize:20 }}>⛏</div>
          <div>
            <div style={{ fontSize:17, fontWeight:700 }}>DELTA MINING</div>
            <div style={{ fontSize:11, color:"#F4A027", letterSpacing:2, textTransform:"uppercase" }}>Panel de Operaciones · R_OP02_FS</div>
          </div>
        </div>
        <div style={{ fontSize:11, color:"#444" }}>📅 {fmtDate(allDates[0])} → {fmtDate(allDates[allDates.length-1])} · {RAW_DATA.length} registros</div>
      </div>

      <div style={{ padding:"20px 24px" }}>

        <div style={{ display:"flex", gap:8, marginBottom:16 }}>
          {[["dia","📅 Por día"],["periodo","📆 Por período"]].map(([m,label]) => (
            <button key={m} onClick={() => setMode(m)} style={{
              background: mode===m ? "#F4A027" : "#1a1d24",
              border:"1px solid "+(mode===m ? "#F4A027" : "#2a2d3a"),
              borderRadius:6, color:mode===m ? "#000" : "#888",
              padding:"7px 16px", fontSize:13, fontWeight:600, cursor:"pointer"
            }}>{label}</button>
          ))}
        </div>

        <div style={{ background:"#13161e", padding:"16px 18px", borderRadius:10, border:"1px solid #1e2130", marginBottom:18 }}>
          <div style={{ display:"flex", gap:12, flexWrap:"wrap", alignItems:"flex-end" }}>

            {mode === "dia" ? (
              <Sel label="Fecha" value={selectedDate} onChange={setSelectedDate}
                options={allDates.map(d => ({value:d, label:fmtDate(d)}))} />
            ) : (
              <>
                <div style={{ display:"flex", flexDirection:"column", gap:6 }}>
                  <div style={{ fontSize:11, color:"#F4A027", textTransform:"uppercase", letterSpacing:1 }}>Desde</div>
                  <div style={{ display:"flex", gap:6 }}>
                    <Sel label="Año"  value={fromYear}  onChange={setFromYear}  options={yearOpts} />
                    <Sel label="Mes"  value={fromMonth} onChange={setFromMonth} options={monthOpts} />
                    <Sel label="Día"  value={fromDay}   onChange={setFromDay}   options={dayOpts} />
                  </div>
                </div>
                <div style={{ alignSelf:"flex-end", paddingBottom:8, color:"#444", fontSize:20 }}>→</div>
                <div style={{ display:"flex", flexDirection:"column", gap:6 }}>
                  <div style={{ fontSize:11, color:"#2A9D8F", textTransform:"uppercase", letterSpacing:1 }}>Hasta</div>
                  <div style={{ display:"flex", gap:6 }}>
                    <Sel label="Año"  value={toYear}  onChange={setToYear}  options={yearOpts} />
                    <Sel label="Mes"  value={toMonth} onChange={setToMonth} options={monthOpts} />
                    <Sel label="Día"  value={toDay}   onChange={setToDay}   options={dayOpts} />
                  </div>
                </div>
              </>
            )}

            <div style={{ width:"1px", background:"#1e2130", alignSelf:"stretch", margin:"0 6px" }} />
            <Sel label="Tipo equipo" value={filterTipo} onChange={v => { setFilterTipo(v); setFilterEquipo("Todos"); }} options={allTipos.map(t => ({value:t,label:t}))} />
            <Sel label="Equipo"      value={filterEquipo} onChange={setFilterEquipo} options={allEquipos.map(t => ({value:t,label:t}))} />
          </div>

          {mode === "periodo" && (
            <div style={{ marginTop:10, fontSize:12, color:"#555" }}>
              Período seleccionado: <span style={{color:"#E8E8E8"}}>{fmtDate(dateFrom)}</span> al <span style={{color:"#E8E8E8"}}>{fmtDate(dateTo)}</span>
              {filtered.length > 0 && <span style={{color:"#F4A027", marginLeft:12}}>· {diasCub} días con datos · {filtered.length} partes</span>}
            </div>
          )}
        </div>

        <div style={{ display:"grid", gridTemplateColumns:"repeat(auto-fit,minmax(140px,1fr))", gap:10, marginBottom:20 }}>
          <KPI label="Horas Totales" value={totalHoras.toFixed(0)+"h"} sub={mode==="periodo"?`en ${diasCub} días`:"trabajadas"} color="#F4A027"/>
          <KPI label="Combustible"   value={totalComb.toFixed(0)+"L"}  sub="consumidos" color="#E8622A"/>
          <KPI label="Equipos"       value={equiposAct}                 sub="activos" color="#2A9D8F"/>
          <KPI label="Operadores"    value={operadores}                 sub="distintos" color="#457B9D"/>
          <KPI label="Partes"        value={filtered.length}            sub="registros" color="#A8DADC"/>
          <KPI label="Desgaste"      value={alertas}                    sub="alertas" color={alertas>0?"#E76F51":"#2A9D8F"}/>
        </div>

        <div style={{ display:"flex", borderBottom:"1px solid #1e2130", marginBottom:18, gap:2 }}>
          {[["resumen","📊 Resumen"],["tendencia","📈 Tendencia"],["equipos","🚧 Equipos"],["partes","📋 Partes"],["desgaste","⚠️ Desgaste"]].map(([t,label]) => (
            <button key={t} onClick={() => setTab(t)} style={{
              background:"none", border:"none",
              borderBottom:tab===t?"2px solid #F4A027":"2px solid transparent",
              color:tab===t?"#F4A027":"#555",
              padding:"8px 14px", fontSize:13, fontWeight:600, cursor:"pointer"
            }}>{label}</button>
          ))}
        </div>

        {tab==="resumen" && (
          <div style={{ display:"grid", gridTemplateColumns:"repeat(auto-fit,minmax(280px,1fr))", gap:14 }}>
            <div style={{ background:"#13161e", borderRadius:10, padding:18, border:"1px solid #1e2130" }}>
              <div style={{ fontSize:12, color:"#F4A027", fontWeight:600, marginBottom:12 }}>Horas por tipo de equipo</div>
              <ResponsiveContainer width="100%" height={180}>
                <BarChart data={horasPorTipo} layout="vertical">
                  <XAxis type="number" tick={{fill:"#444",fontSize:9}}/>
                  <YAxis dataKey="tipo" type="category" tick={{fill:"#aaa",fontSize:10}} width={130}/>
                  <Tooltip contentStyle={{background:"#0D0F14",border:"1px solid #333",borderRadius:6}}/>
                  <Bar dataKey="horas" radius={[0,3,3,0]}>
                    {horasPorTipo.map((_,i) => <Cell key={i} fill={COLORS[i%COLORS.length]}/>)}
                  </Bar>
                </BarChart>
              </ResponsiveContainer>
            </div>
            {proyectos.length>0 && (
              <div style={{ background:"#13161e", borderRadius:10, padding:18, border:"1px solid #1e2130" }}>
                <div style={{ fontSize:12, color:"#F4A027", fontWeight:600, marginBottom:12 }}>Horas por proyecto</div>
                <ResponsiveContainer width="100%" height={180}>
                  <PieChart>
                    <Pie data={proyectos} dataKey="value" nameKey="name" cx="50%" cy="50%" outerRadius={70}
                      label={({name,percent}) => `${name} ${(percent*100).toFixed(0)}%`}>
                      {proyectos.map((_,i) => <Cell key={i} fill={COLORS[i%COLORS.length]}/>)}
                    </Pie>
                    <Tooltip contentStyle={{background:"#0D0F14",border:"1px solid #333",borderRadius:6}}/>
                  </PieChart>
                </ResponsiveContainer>
              </div>
            )}
            <div style={{ background:"#13161e", borderRadius:10, padding:18, border:"1px solid #1e2130" }}>
              <div style={{ fontSize:12, color:"#2A9D8F", fontWeight:600, marginBottom:12 }}>Top horas por equipo</div>
              <ResponsiveContainer width="100%" height={180}>
                <BarChart data={porEquipo.slice(0,8)}>
                  <XAxis dataKey="interno" tick={{fill:"#444",fontSize:9}}/>
                  <YAxis tick={{fill:"#444",fontSize:9}}/>
                  <Tooltip contentStyle={{background:"#0D0F14",border:"1px solid #333",borderRadius:6}}/>
                  <Bar dataKey="horas" fill="#2A9D8F" radius={[3,3,0,0]}/>
                </BarChart>
              </ResponsiveContainer>
            </div>
            <div style={{ background:"#13161e", borderRadius:10, padding:18, border:"1px solid #1e2130" }}>
              <div style={{ fontSize:12, color:"#E8622A", fontWeight:600, marginBottom:12 }}>Top combustible por equipo</div>
              <ResponsiveContainer width="100%" height={180}>
                <BarChart data={porEquipo.filter(r=>r.combustible>0).slice(0,8)}>
                  <XAxis dataKey="interno" tick={{fill:"#444",fontSize:9}}/>
                  <YAxis tick={{fill:"#444",fontSize:9}}/>
                  <Tooltip contentStyle={{background:"#0D0F14",border:"1px solid #333",borderRadius:6}}/>
                  <Bar dataKey="combustible" fill="#E8622A" radius={[3,3,0,0]}/>
                </BarChart>
              </ResponsiveContainer>
            </div>
          </div>
        )}

        {tab==="tendencia" && (
          <div style={{ display:"flex", flexDirection:"column", gap:14 }}>
            <div style={{ display:"flex", gap:8 }}>
              {PARAMS.map(p => (
                <button key={p.key} onClick={() => setParamKey(p.key)} style={{
                  background:paramKey===p.key?p.color:"#1a1d24",
                  border:"1px solid "+(paramKey===p.key?p.color:"#2a2d3a"),
                  borderRadius:6, color:paramKey===p.key?"#000":"#888",
                  padding:"6px 14px", fontSize:12, fontWeight:600, cursor:"pointer"
                }}>{p.label}</button>
              ))}
            </div>
            <div style={{ background:"#13161e", borderRadius:10, padding:18, border:"1px solid #1e2130" }}>
              <div style={{ fontSize:12, color:paramColor, fontWeight:600, marginBottom:12 }}>
                {paramLabel} — {mode==="dia" ? fmtDate(selectedDate) : `${fmtDate(dateFrom)} al ${fmtDate(dateTo)}`}
              </div>
              <ResponsiveContainer width="100%" height={260}>
                <LineChart data={serieTemporal}>
                  <CartesianGrid strokeDasharray="3 3" stroke="#1e2130"/>
                  <XAxis dataKey="dia" tick={{fill:"#444",fontSize:9}}/>
                  <YAxis tick={{fill:"#444",fontSize:9}}/>
                  <Tooltip contentStyle={{background:"#0D0F14",border:"1px solid #333",borderRadius:6}}/>
                  <Line type="monotone" dataKey={paramKey} stroke={paramColor} strokeWidth={2} dot={false}/>
                </LineChart>
              </ResponsiveContainer>
            </div>
            {serieTemporal.length > 1 && (() => {
              const vals = serieTemporal.map(d => d[paramKey]);
              const avg  = vals.reduce((a,b)=>a+b,0)/vals.length;
              const max  = Math.max(...vals);
              const min  = Math.min(...vals);
              const maxDia = serieTemporal.find(d=>d[paramKey]===max)?.dia;
              const minDia = serieTemporal.find(d=>d[paramKey]===min)?.dia;
              return (
                <div style={{ display:"grid", gridTemplateColumns:"repeat(auto-fit,minmax(160px,1fr))", gap:10 }}>
                  <KPI label="Promedio diario" value={avg.toFixed(1)}              color={paramColor}/>
                  <KPI label="Máximo"          value={max} sub={`el ${maxDia}`}   color="#2A9D8F"/>
                  <KPI label="Mínimo"          value={min} sub={`el ${minDia}`}   color="#E76F51"/>
                  <KPI label="Total período"   value={vals.reduce((a,b)=>a+b,0).toFixed(0)} color="#457B9D"/>
                </div>
              );
            })()}
          </div>
        )}

        {tab==="equipos" && (
          <div style={{ overflowX:"auto" }}>
            <table style={{ width:"100%", borderCollapse:"collapse", fontSize:13 }}>
              <thead>
                <tr style={{ borderBottom:"1px solid #1e2130" }}>
                  {["Interno","Tipo","Operador","Turno","Horas","Combustible","Horóm. Final"].map(h => (
                    <th key={h} style={{ padding:"9px 12px", textAlign:"left", color:"#555", fontSize:11, textTransform:"uppercase", letterSpacing:1 }}>{h}</th>
                  ))}
                </tr>
              </thead>
              <tbody>
                {filtered.map((r,i) => (
                  <tr key={i} style={{ borderBottom:"1px solid #13161e", background:i%2===0?"transparent":"rgba(255,255,255,0.015)" }}>
                    <td style={{ padding:"8px 12px", color:"#F4A027", fontWeight:600 }}>{r.interno}</td>
                    <td style={{ padding:"8px 12px", color:"#888" }}>{r.tipo}</td>
                    <td style={{ padding:"8px 12px" }}>{r.operador}</td>
                    <td style={{ padding:"8px 12px" }}>
                      <span style={{ background:r.turno?.includes("NOCHE")?"#0e1a24":"#1f1208", color:r.turno?.includes("NOCHE")?"#7EC8E3":"#F4A027", padding:"2px 7px", borderRadius:4, fontSize:11 }}>{r.turno}</span>
                    </td>
                    <td style={{ padding:"8px 12px", fontWeight:600 }}>{r.horas}h</td>
                    <td style={{ padding:"8px 12px", color:r.combustible>0?"#E8622A":"#333" }}>{r.combustible>0?r.combustible+"L":"—"}</td>
                    <td style={{ padding:"8px 12px", color:"#555" }}>{r.horomFinal}</td>
                  </tr>
                ))}
              </tbody>
            </table>
            {filtered.length===0 && <div style={{color:"#333",padding:24,textAlign:"center"}}>Sin registros.</div>}
          </div>
        )}

        {tab==="desgaste" && (
          <div style={{ display:"flex", flexDirection:"column", gap:12 }}>
            {desgastePorEquipo.length === 0 && (
              <div style={{color:"#333",padding:24,textAlign:"center"}}>Sin registros de desgaste para el filtro seleccionado.</div>
            )}
            {desgastePorEquipo.map(equipo => (
              <EquipoDesgaste key={equipo.interno} equipo={equipo} />
            ))}
          </div>
        )}

        {tab==="partes" && (
          <div style={{ display:"flex", flexDirection:"column", gap:8 }}>
            {filtered.map((r,i) => (
              <div key={i} style={{ background:"#13161e", borderRadius:8, padding:"13px 16px", border:"1px solid #1e2130", display:"grid", gridTemplateColumns:"100px 1fr auto", gap:"0 14px", alignItems:"start" }}>
                <div>
                  <div style={{ color:"#F4A027", fontWeight:700 }}>{r.interno}</div>
                  <div style={{ color:"#444", fontSize:11 }}>Parte #{r.nParte}</div>
                  <div style={{ color:"#555", fontSize:11 }}>{r.fecha.split('-').reverse().join('/')}</div>
                  <div style={{ color:"#333", fontSize:11 }}>{r.proyecto}</div>
                </div>
                <div>
                  <div style={{ fontWeight:600, marginBottom:3 }}>{r.operador}</div>
                  <div style={{ color:"#666", fontSize:12 }}>{r.descripcion}</div>
                  {r.desgaste && r.desgaste!=="Sin consumo de desgaste" && (
                    <div style={{ color:"#E76F51", fontSize:11, marginTop:4 }}>⚠ {r.desgaste}</div>
                  )}
                </div>
                <div style={{ textAlign:"right" }}>
                  <div style={{ fontWeight:700, color:"#2A9D8F" }}>{r.horas}h</div>
                  {r.combustible>0 && <div style={{ color:"#E8622A", fontSize:12 }}>{r.combustible}L</div>}
                  <div style={{ marginTop:4 }}>
                    <span style={{ background:r.turno?.includes("NOCHE")?"#0e1a24":"#1f1208", color:r.turno?.includes("NOCHE")?"#7EC8E3":"#F4A027", padding:"2px 6px", borderRadius:4, fontSize:10 }}>{r.turno}</span>
                  </div>
                </div>
              </div>
            ))}
            {filtered.length===0 && <div style={{color:"#333",padding:24,textAlign:"center"}}>Sin registros.</div>}
          </div>
        )}

      </div>
    </div>
  );
}
